// Minimal TypeBox-compatible stub for tests of docs/v3/guides/community/dgs-integrations/pi-mono/agent/extensions/honcho.ts.
// The extension calls Type.* only to build parameter schemas which are handed to pi.registerTool and never
// evaluated by the extension itself, so an inert stub is sufficient. This avoids fetching the real package.
const withOpts = (type) => (opts = {}) => ({ type, ...opts });

const Type = {
  Any: (opts = {}) => ({ ...opts }),
  String: withOpts("string"),
  Number: withOpts("number"),
  Boolean: withOpts("boolean"),
  Object: (properties, opts = {}) => ({ type: "object", properties, ...opts }),
  Record: (_key, value) => ({ type: "object", additionalProperties: value }),
  Optional: (schema) => schema,
  // Unknown combinators are tolerated so the stub never throws on version drift.
};

module.exports = { Type };